import{_ as o,o as e,c as i,ak as l,al as r,am as t,an as d,ao as n,ap as h,aq as s,ar as c}from"./chunks/framework.DDz3O3n6.js";const u=JSON.parse('{"title":"Godot 4 安装教程（Windows 2026最新版）｜下载、安装、创建第一个项目（完整指南）","description":"","frontmatter":{},"headers":[],"relativePath":"godot/godot-4-installation.md","filePath":"godot/godot-4-installation.md","lastUpdated":1780762458000}'),p={name:"godot/godot-4-installation.md"};function g(_,a,b,m,G,f){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="godot-4-安装教程-windows-2026最新版-下载、安装、创建第一个项目-完整指南" tabindex="-1">Godot 4 安装教程（Windows 2026最新版）｜下载、安装、创建第一个项目（完整指南） <a class="header-anchor" href="#godot-4-安装教程-windows-2026最新版-下载、安装、创建第一个项目-完整指南" aria-label="Permalink to “Godot 4 安装教程（Windows 2026最新版）｜下载、安装、创建第一个项目（完整指南）”">​</a></h1><p>本教程适用于搜索以下问题的用户：</p><ul><li>Godot 4 安装教程</li><li>Godot 4 Windows 下载</li><li>如何安装 Godot 引擎</li><li>Godot 4 创建第一个项目</li></ul><p>Godot 是一款免费、开源、跨平台的游戏引擎，适合独立开发者、初学者和小团队使用。<br> 本文将以 <strong>Windows</strong> 为例，带你完成 <strong>Godot 4 下载、安装、首次启动和创建第一个项目</strong>。</p><p>官网地址：<a href="https://godotengine.org/zh-cn/" target="_blank" rel="noreferrer">https://godotengine.org/zh-cn/</a></p><hr><h2 id="一、下载-godot-4" tabindex="-1">一、下载 Godot 4 <a class="header-anchor" href="#一、下载-godot-4" aria-label="Permalink to “一、下载 Godot 4”">​</a></h2><p>Godot 可以从多个渠道下载，建议优先使用官方渠道。</p><h3 id="_1-官方下载页" tabindex="-1">1. 官方下载页 <a class="header-anchor" href="#_1-官方下载页" aria-label="Permalink to “1. 官方下载页”">​</a></h3><ul><li>Windows 下载页：<a href="https://godotengine.org/download/windows/" target="_blank" rel="noreferrer">https://godotengine.org/download/windows/</a></li><li>官方镜像页：<a href="https://godotengine.itch.io/godot" target="_blank" rel="noreferrer">https://godotengine.itch.io/godot</a></li></ul><h3 id="_2-下载哪个版本" tabindex="-1">2. 下载哪个版本 <a class="header-anchor" href="#_2-下载哪个版本" aria-label="Permalink to “2. 下载哪个版本”">​</a></h3><p>一般情况下，Windows 用户直接下载带有以下后缀的版本即可：</p><ul><li><code>x86_64</code></li><li><code>64-bit</code></li></ul><p>如果你只想用 <strong>GDScript</strong> 开发，直接下载标准版即可。<br> 如果你需要 <strong>C#</strong> 支持，可以选择对应的 C# 版本。</p><blockquote><p>提示：如果网络环境限制导致下载不方便，可以通过社区或交流群获取帮助。</p></blockquote><hr><h2 id="二、安装-godot" tabindex="-1">二、安装 Godot <a class="header-anchor" href="#二、安装-godot" aria-label="Permalink to “二、安装 Godot”">​</a></h2><p>Godot 的安装方式非常简单，它通常不需要传统意义上的“安装程序”。</p><h3 id="_1-解压下载包" tabindex="-1">1. 解压下载包 <a class="header-anchor" href="#_1-解压下载包" aria-label="Permalink to “1. 解压下载包”">​</a></h3><p>下载完成后，你会得到一个压缩包。<br> 解压后，通常会看到两个可执行文件：</p><ul><li><code>Godot_v4.x.x-stable_win64.exe</code></li><li><code>Godot_v4.x.x-stable_win64_console.exe</code></li></ul><h3 id="_2-启动-godot" tabindex="-1">2. 启动 Godot <a class="header-anchor" href="#_2-启动-godot" aria-label="Permalink to “2. 启动 Godot”">​</a></h3><p>一般情况下，直接双击主程序即可：</p><ul><li><code>Godot_v4.x.x-stable_win64.exe</code></li></ul><p>如果你需要查看命令行输出、调试信息或报错信息，可以运行：</p><ul><li><code>Godot_v4.x.x-stable_win64_console.exe</code></li></ul><p><img src="'+r+'" alt="Godot 4 Windows 运行程序示意图"></p><hr><h2 id="三、第一次启动-godot" tabindex="-1">三、第一次启动 Godot <a class="header-anchor" href="#三、第一次启动-godot" aria-label="Permalink to “三、第一次启动 Godot”">​</a></h2><p>首次启动后，你会看到 Godot 的项目管理器界面。<br> 如果系统语言设置正常，界面通常会自动显示为中文。</p><p><img src="'+t+'" alt="Godot 4 Windows 首次启动界面"></p><h3 id="_1-建议使用中文目录" tabindex="-1">1. 建议使用中文目录 <a class="header-anchor" href="#_1-建议使用中文目录" aria-label="Permalink to “1. 建议使用中文目录”">​</a></h3><p>创建项目时，建议尽量把项目放在 <strong>中文路径较少、英文路径清晰</strong> 的目录下。<br> 这样可以减少某些路径识别问题，尤其是在导出、插件或第三方工具配合使用时更稳妥。</p><h3 id="_2-认识项目管理器" tabindex="-1">2. 认识项目管理器 <a class="header-anchor" href="#_2-认识项目管理器" aria-label="Permalink to “2. 认识项目管理器”">​</a></h3><p>你会在这里看到：</p><ul><li>新建项目</li><li>导入项目</li><li>最近打开的项目</li></ul><p>对于新手来说，通常从 <strong>新建项目</strong> 开始即可。</p><hr><h2 id="四、创建第一个项目" tabindex="-1">四、创建第一个项目 <a class="header-anchor" href="#四、创建第一个项目" aria-label="Permalink to “四、创建第一个项目”">​</a></h2><h3 id="_1-点击-新建项目" tabindex="-1">1. 点击“新建项目” <a class="header-anchor" href="#_1-点击-新建项目" aria-label="Permalink to “1. 点击“新建项目””">​</a></h3><p>在项目管理器中点击 <strong>新建项目</strong>。</p><h3 id="_2-填写项目信息" tabindex="-1">2. 填写项目信息 <a class="header-anchor" href="#_2-填写项目信息" aria-label="Permalink to “2. 填写项目信息”">​</a></h3><p>你需要设置：</p><ul><li><strong>项目名称</strong>：例如 <code>MyFirstGame</code></li><li><strong>项目路径</strong>：建议选择一个干净的英文目录</li><li><strong>渲染器</strong>：新手通常保持默认即可</li></ul><h3 id="_3-创建项目" tabindex="-1">3. 创建项目 <a class="header-anchor" href="#_3-创建项目" aria-label="Permalink to “3. 创建项目”">​</a></h3><p>确认无误后，点击创建。<br> Godot 会自动生成项目文件，并打开编辑器。</p><p><img src="'+d+'" alt="Godot 4 Windows 创建项目页面"></p><hr><h2 id="五、创建第一个场景" tabindex="-1">五、创建第一个场景 <a class="header-anchor" href="#五、创建第一个场景" aria-label="Permalink to “五、创建第一个场景”">​</a></h2><p>Godot 的开发方式非常核心的一点，就是 <strong>先做场景，再做游戏逻辑</strong>。</p><h3 id="_1-新建场景" tabindex="-1">1. 新建场景 <a class="header-anchor" href="#_1-新建场景" aria-label="Permalink to “1. 新建场景”">​</a></h3><p>在目录中右键</p><p><img src="'+n+'" alt="Godot 4 Windows 创建场景页面"></p><h3 id="_2-添加根节点" tabindex="-1">2. 添加根节点 <a class="header-anchor" href="#_2-添加根节点" aria-label="Permalink to “2. 添加根节点”">​</a></h3><p>一般可以从以下节点开始：</p><ul><li><code>Node2D</code> ：适合 2D 游戏</li><li><code>Control</code>：适合 UI 界面</li><li><code>Node3D</code>：适合 3D 游戏</li></ul><p>如果你是第一次接触 Godot，建议先从 <strong>Node2D</strong> 开始。</p><p><img src="'+h+'" alt="Godot 4 Windows 新建场景页面"></p><h3 id="_3-保存场景" tabindex="-1">3. 保存场景 <a class="header-anchor" href="#_3-保存场景" aria-label="Permalink to “3. 保存场景”">​</a></h3><p>把场景保存为：</p><ul><li><code>main.tscn</code></li></ul><p>建议把它放在项目根目录的 <code>scenes</code> 文件夹里，方便管理。</p><hr><h2 id="六、运行你的第一个项目" tabindex="-1">六、运行你的第一个项目 <a class="header-anchor" href="#六、运行你的第一个项目" aria-label="Permalink to “六、运行你的第一个项目”">​</a></h2><h3 id="_1-设置主场景" tabindex="-1">1. 设置主场景 <a class="header-anchor" href="#_1-设置主场景" aria-label="Permalink to “1. 设置主场景”">​</a></h3><p>保存场景后，将它设置为主场景。<br> 这样按下运行按钮时，Godot 会直接启动这个场景。</p><h3 id="_2-点击运行" tabindex="-1">2. 点击运行 <a class="header-anchor" href="#_2-点击运行" aria-label="Permalink to “2. 点击运行”">​</a></h3><p>点击编辑器右上角的运行按钮，或者按快捷键运行项目。</p><p><img src="'+s+'" alt="Godot 4 Windows 编辑器运行按钮"></p><p>如果显示如下，请点击: 选择当前</p><p><img src="'+c+'" alt="Godot 4 Windows 编辑器首次运行选择场景"></p><p>如果一切正常，你就已经成功完成了：</p><ul><li>下载</li><li>安装</li><li>创建项目</li><li>创建场景</li><li>运行项目</li></ul><p>这意味着你的 Godot 环境已经可以正常使用了。</p><hr><h2 id="七、常见问题" tabindex="-1">七、常见问题 <a class="header-anchor" href="#七、常见问题" aria-label="Permalink to “七、常见问题”">​</a></h2><h3 id="_1-godot-打不开怎么办" tabindex="-1">1. Godot 打不开怎么办？ <a class="header-anchor" href="#_1-godot-打不开怎么办" aria-label="Permalink to “1. Godot 打不开怎么办？”">​</a></h3><p>可以先检查以下几点：</p><ul><li>是否下载了正确的 Windows 版本</li><li>文件是否被压缩包完整解压</li><li>系统是否缺少运行环境</li><li>是否误点了 console 版本并误以为程序没反应</li></ul><h3 id="_2-为什么项目路径最好不要太复杂" tabindex="-1">2. 为什么项目路径最好不要太复杂？ <a class="header-anchor" href="#_2-为什么项目路径最好不要太复杂" aria-label="Permalink to “2. 为什么项目路径最好不要太复杂？”">​</a></h3><p>路径过长、包含特殊符号、空格过多，偶尔会引起一些兼容问题。<br> 新手阶段建议尽量使用简单路径。</p><h3 id="_3-godot-需要安装吗" tabindex="-1">3. Godot 需要安装吗？ <a class="header-anchor" href="#_3-godot-需要安装吗" aria-label="Permalink to “3. Godot 需要安装吗？”">​</a></h3><p>大多数情况下不需要。<br> Godot 的 Windows 版本通常是 <strong>解压即用</strong>。</p><h3 id="_4-godot-支持-c-吗" tabindex="-1">4. Godot 支持 C# 吗？ <a class="header-anchor" href="#_4-godot-支持-c-吗" aria-label="Permalink to “4. Godot 支持 C# 吗？”">​</a></h3><p>支持。<br> 如果你想用 C# 开发，请下载带有 C# 支持的版本。</p><hr><h2 id="八、获取帮助" tabindex="-1">八、获取帮助 <a class="header-anchor" href="#八、获取帮助" aria-label="Permalink to “八、获取帮助”">​</a></h2><p>如果你在安装或启动 Godot 时遇到问题，可以通过以下方式获取帮助：</p><ul><li>QQ 群：<code>289132257</code></li><li>GitHub Issues：<a href="https://github.com/licheng1013/licheng1013.github.io/issues" target="_blank" rel="noreferrer">https://github.com/licheng1013/licheng1013.github.io/issues</a></li></ul><p>如果你愿意，也可以直接把问题截图发出来，通常更容易定位。</p><hr><h2 id="九、下一步学什么" tabindex="-1">九、下一步学什么 <a class="header-anchor" href="#九、下一步学什么" aria-label="Permalink to “九、下一步学什么”">​</a></h2><p>完成安装后，建议继续学习：</p><ul><li>Godot 编辑器界面介绍</li><li>节点和场景是什么</li><li>GDScript 基础语法</li><li>第一个 2D 小游戏</li><li>输入、碰撞、动画和 UI</li></ul><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>Godot 4 的安装并不复杂，Windows 用户一般只要做到这几步就够了：</p><ol><li>下载官方版本</li><li>解压压缩包</li><li>运行主程序</li><li>创建项目</li><li>新建场景并运行</li></ol><p>如果你是刚接触 Godot，先把这一步走通，比直接学复杂功能更重要。</p>',99)])])}const k=o(p,[["render",g]]);export{u as __pageData,k as default};
